  if (updates.agent !== undefined) {
    sets.push('agent = ?');
    values.push(updates.agent);
  }
  if (updates.priority !== undefined) {
    sets.push('priority = ?');
    values.push(updates.priority);
  }
  if (updates.notes !== undefined) {
    sets.push('notes = ?');
    values.push(updates.notes);
  }
  if (updates.summary !== undefined) {
    sets.push('summary = ?');
    values.push(updates.summary);
  }
  if (updates.dependencies !== undefined) {
    sets.push('dependencies = ?');
    values.push(JSON.stringify(updates.dependencies));
  }
  if (updates.relatedFiles !== undefined || updates.related_files !== undefined) {
    sets.push('related_files = ?');
    values.push(JSON.stringify(updates.relatedFiles || updates.related_files));
  }

  // Always update timestamp
  sets.push('updated_at = ?');
  values.push(Date.now());

  // Add taskId at the end for WHERE clause
  values.push(taskId);

  // 1. Update SQLite
  const result = db.prepare(`
    UPDATE workflow_tasks
    SET ${sets.join(', ')}
    WHERE id = ?
  `).run(...values);

