#!/usr/bin/env bun

// Quick integration test for timestamp fixes
import { Database } from 'bun:sqlite';

console.log('🔧 Testing Timestamp Fixes...');

// Initialize test database
const db = new Database(':memory:');

// Create test table structure
db.exec(`
  CREATE TABLE workflow_tasks (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT,
    status TEXT DEFAULT 'pending',
    agent TEXT DEFAULT 'primary',
    session_id TEXT DEFAULT 'default',
    implementation_guide TEXT,
    verification_criteria TEXT,
    analysis_result TEXT,
    notes TEXT,
    summary TEXT,
    dependencies TEXT DEFAULT '[]',
    related_files TEXT DEFAULT '[]',
    priority TEXT DEFAULT 'medium',
    created_at INTEGER NOT NULL DEFAULT (strftime('%s', 'now') * 1000),
    updated_at INTEGER NOT NULL DEFAULT (strftime('%s', 'now') * 1000),
    completed_at INTEGER,
    shrimp_sync_version INTEGER DEFAULT 0,
    version INTEGER DEFAULT 1
  )
`);

// Test 1: Insert task with current timestamp (should be milliseconds)
console.log('📝 Test 1: Creating task with current timestamp...');
const testTaskId = `test-${Date.now()}`;
const currentTime = Date.now(); // milliseconds

db.prepare(`
  INSERT INTO workflow_tasks (id, name, created_at, updated_at)
  VALUES (?, ?, ?, ?)
`).run(testTaskId, 'Test Task', currentTime, currentTime);

// Test 2: Verify stored timestamps
console.log('✅ Test 2: Verifying stored timestamps...');
const storedTask = db.prepare('SELECT * FROM workflow_tasks WHERE id = ?').get(testTaskId);

console.log(`   • Stored created_at: ${storedTask.created_at}`);
console.log(`   • Stored updated_at: ${storedTask.updated_at}`);
console.log(`   • Expected (current): ${currentTime}`);

const createdDate = new Date(storedTask.created_at);
const updatedDate = new Date(storedTask.updated_at);

console.log(`   • Created date: ${createdDate.toISOString()}`);
console.log(`   • Updated date: ${updatedDate.toISOString()}`);

// Test 3: Verify timestamps are in 2025 (not 1970)
console.log('📅 Test 3: Checking year consistency...');
const createdYear = createdDate.getFullYear();
const updatedYear = updatedDate.getFullYear();

console.log(`   • Created year: ${createdYear}`);
console.log(`   • Updated year: ${updatedYear}`);

// Test 4: Update task and check timestamp
console.log('🔄 Test 4: Testing update with new timestamp...');
const updateTime = Date.now();

db.prepare(`
  UPDATE workflow_tasks 
  SET status = 'completed', completed_at = ?, updated_at = ?
  WHERE id = ?
`).run(updateTime, updateTime, testTaskId);

const updatedTask = db.prepare('SELECT * FROM workflow_tasks WHERE id = ?').get(testTaskId);
const completedDate = new Date(updatedTask.completed_at);
const newUpdatedDate = new Date(updatedTask.updated_at);

console.log(`   • Completed date: ${completedDate.toISOString()}`);
console.log(`   • New updated date: ${newUpdatedDate.toISOString()}`);

// Results Summary
console.log('\n🎯 Test Results Summary:');
console.log('========================');

const allTests = [
  {
    name: 'Timestamp Storage Format',
    passed: storedTask.created_at === currentTime && storedTask.updated_at === currentTime,
