import { Database } from 'bun:sqlite';
import { watch } from 'fs';
import { readFile, writeFile } from 'fs/promises';
import path from 'path';

// Shrimp tasks file location
const SHRIMP_TASKS_FILE = '/Users/sam/ShrimpData/claude-code-hooks-mastery/tasks.json';
const SHRIMP_BACKUP_DIR = '/Users/sam/ShrimpData/claude-code-hooks-mastery/memory';

// WebSocket connections for real-time updates
const wsConnections = new Set<any>();

// Database instance
let db: Database;

// Debounce timer for file watcher
let debounceTimer: NodeJS.Timeout | null = null;
const DEBOUNCE_DELAY = 500; // 500ms debounce

// Track sync status to prevent loops
let isSyncing = false;

export function initWorkflowBridge(database: Database) {
  db = database;

  // Start file watcher
  initShrimpSync();

  // Initial sync on startup
  syncFromShrimpToSQLite().catch(console.error);
}

// Add WebSocket connection
export function addWebSocketConnection(ws: any) {
  wsConnections.add(ws);
  ws.on('close', () => wsConnections.delete(ws));
}

// Broadcast to all connected clients
function broadcastUpdate(event: string, data: any) {
  const message = JSON.stringify({ event, data });
  wsConnections.forEach(ws => {
    if (ws.readyState === 1) { // OPEN
      ws.send(message);
    }
  });
}

// File watcher for automatic synchronization with debounce
function initShrimpSync() {
  // Watch for changes in Shrimp tasks file
  watch(SHRIMP_TASKS_FILE, async (eventType) => {
    if (eventType === 'change' && !isSyncing) {
      // Clear existing timer
      if (debounceTimer) {
        clearTimeout(debounceTimer);
      }

      // Set new debounced sync
      debounceTimer = setTimeout(async () => {
        console.log('[Sync] Detected change in Shrimp tasks.json (debounced)');
        await syncFromShrimpToSQLite();
      }, DEBOUNCE_DELAY);
    }
  });

  console.log('[Sync] File watcher initialized with debounce for:', SHRIMP_TASKS_FILE);
}

// Sync from Shrimp → SQLite (READ)
export async function syncFromShrimpToSQLite() {
  try {
    const fileContent = await readFile(SHRIMP_TASKS_FILE, 'utf-8');
    const shrimpData = JSON.parse(fileContent);
    const tasks = shrimpData.tasks || [];

    console.log(`[Sync] Syncing ${tasks.length} tasks from Shrimp to SQLite`);

    const upsertStmt = db.prepare(`
      INSERT OR REPLACE INTO workflow_tasks (
        id, name, description, status, agent, session_id,
        implementation_guide, verification_criteria, analysis_result,
        notes, summary, dependencies, related_files, priority,
        created_at, updated_at, completed_at, shrimp_sync_version, version
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    const transaction = db.transaction(() => {
      for (const task of tasks) {
        upsertStmt.run(
          task.id,
          task.name,
          task.description || null,
          task.status || 'pending',
          task.agent || 'primary',
          task.session_id || 'default',
          task.implementationGuide || null,
          task.verificationCriteria || null,
          task.analysisResult || null,
          task.notes || null,
          task.summary || null,
          JSON.stringify(task.dependencies || []),
          JSON.stringify(task.relatedFiles || []),
          task.priority || 'medium',
          task.createdAt ? new Date(task.createdAt).getTime() : Date.now(),
          task.updatedAt ? new Date(task.updatedAt).getTime() : Date.now(),
          task.completedAt ? new Date(task.completedAt).getTime() : null,
          Date.now(), // sync version
          1 // version for optimistic locking
        );
      }
    });

    transaction();

    // Broadcast update to WebSocket clients
    broadcastUpdate('tasks_synced', { count: tasks.length, source: 'shrimp' });

    console.log(`[Sync] Successfully synced ${tasks.length} tasks`);
    return tasks;

  } catch (error) {
    console.error('[Sync] Failed to sync from Shrimp:', error);
    return [];
  }
}

// Write-through: SQLite → Shrimp (WRITE)
export async function syncToShrimpFile(taskId?: string) {
  // Set sync flag to prevent loop
  isSyncing = true;

  try {
    // Read current Shrimp state
    let shrimpData = { tasks: [] };
    try {
      const fileContent = await readFile(SHRIMP_TASKS_FILE, 'utf-8');
      shrimpData = JSON.parse(fileContent);
    } catch (error) {
      console.log('[Sync] Creating new Shrimp tasks file');
    }

    let shrimpTasks = shrimpData.tasks || [];

    if (taskId) {
      // Sync single task
      const sqliteTask = db.prepare(`
        SELECT * FROM workflow_tasks WHERE id = ?
      `).get(taskId) as any;

      if (sqliteTask) {
        // Convert SQLite format → Shrimp format
        const shrimpTask = {
          id: sqliteTask.id,
          name: sqliteTask.name,
          description: sqliteTask.description,
          status: sqliteTask.status,
          agent: sqliteTask.agent,
          session_id: sqliteTask.session_id,
          notes: sqliteTask.notes,
          dependencies: JSON.parse(sqliteTask.dependencies || '[]'),
          relatedFiles: JSON.parse(sqliteTask.related_files || '[]'),
          implementationGuide: sqliteTask.implementation_guide,
          verificationCriteria: sqliteTask.verification_criteria,
          analysisResult: sqliteTask.analysis_result,
          summary: sqliteTask.summary,
          priority: sqliteTask.priority,
          createdAt: new Date(sqliteTask.created_at * 1000).toISOString(),
          updatedAt: new Date(sqliteTask.updated_at * 1000).toISOString(),
          completedAt: sqliteTask.completed_at 
            ? new Date(sqliteTask.completed_at * 1000).toISOString()
            : undefined
        };

        // Update or insert in array
        const index = shrimpTasks.findIndex((t: any) => t.id === taskId);
        if (index >= 0) {
          shrimpTasks[index] = shrimpTask;
        } else {
          shrimpTasks.push(shrimpTask);
        }
      }
    } else {
      // Full sync (all tasks)
      const allTasks = db.prepare(`
        SELECT * FROM workflow_tasks ORDER BY created_at DESC
      `).all() as any[];

      // Convert all tasks
      shrimpTasks = allTasks.map(task => ({
        id: task.id,
        name: task.name,
        description: task.description,
        status: task.status,
        agent: task.agent,
        session_id: task.session_id,
        notes: task.notes,
        dependencies: JSON.parse(task.dependencies || '[]'),
        relatedFiles: JSON.parse(task.related_files || '[]'),
        implementationGuide: task.implementation_guide,
        verificationCriteria: task.verification_criteria,
        analysisResult: task.analysis_result,
        summary: task.summary,
        priority: task.priority,
        createdAt: new Date(task.created_at).toISOString(),
        updatedAt: new Date(task.updated_at).toISOString(),
        completedAt: task.completed_at 
          ? new Date(task.completed_at).toISOString()
          : undefined
      }));
    }

    // Write updated file
    await writeFile(
      SHRIMP_TASKS_FILE,
      JSON.stringify({ tasks: shrimpTasks }, null, 2),
      'utf-8'
    );

    console.log(`[Sync] Successfully synced to Shrimp file`);
    return true;

  } catch (error) {
    console.error('[Sync] Failed to sync to Shrimp:', error);
    return false;
  } finally {
    // Reset sync flag after a delay to allow file system to settle
    setTimeout(() => {
      isSyncing = false;
    }, 100);
  }
}

// Get workflow tasks from SQLite (fast read)
export async function getWorkflowTasks(sessionId?: string) {
  const tasks = db.prepare(`
    SELECT * FROM workflow_tasks
    WHERE (session_id = ? OR ? IS NULL)
    ORDER BY
      CASE status
        WHEN 'in_progress' THEN 1
        WHEN 'pending' THEN 2
        WHEN 'completed' THEN 3
      END,
      updated_at DESC
  `).all(sessionId, sessionId) as any[];

  // Parse JSON fields
  return tasks.map(task => ({
    ...task,
    dependencies: JSON.parse(task.dependencies || '[]'),
    related_files: JSON.parse(task.related_files || '[]'),
    created_at: new Date(task.created_at).toISOString(),
    updated_at: new Date(task.updated_at).toISOString(),
    completed_at: task.completed_at 
      ? new Date(task.completed_at).toISOString()
      : null
  }));
}

// Create workflow task with write-through
export async function createWorkflowTask(data: any) {
  const id = data.id || `task-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

  // 1. Insert in SQLite (immediate)
  db.prepare(`
    INSERT INTO workflow_tasks (
      id, name, description, status, agent, session_id, 
      priority, dependencies, related_files, notes,
      implementation_guide, verification_criteria
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).run(
    id, 
    data.name, 
    data.description || null, 
    data.status || 'pending',
    data.agent || 'primary', 
    data.sessionId || data.session_id || 'default',
    data.priority || 'medium', 
    JSON.stringify(data.dependencies || []),
    JSON.stringify(data.relatedFiles || data.related_files || []),
    data.notes || null,
    data.implementationGuide || data.implementation_guide || null,
    data.verificationCriteria || data.verification_criteria || null
  );

  // 2. Sync to Shrimp file (async)
  setImmediate(() => syncToShrimpFile(id));

  // 3. WebSocket broadcast
  broadcastUpdate('task_created', { id, ...data });

  return { success: true, data: { id, ...data } };
}

// Update workflow task with optimistic locking
export async function updateWorkflowTask(taskId: string, updates: any, expectedVersion?: number) {
  // Retry logic for version conflicts
  let retries = 3;

  while (retries > 0) {
    // Get current task version if not provided
    if (!expectedVersion) {
      const currentTask = db.prepare('SELECT version FROM workflow_tasks WHERE id = ?').get(taskId) as any;
      if (!currentTask) {
        return { success: false, error: 'Task not found' };
      }
      expectedVersion = currentTask.version;
    }

    // Build dynamic UPDATE query
    const sets = [];
    const values = [];

    if (updates.status !== undefined) {
      sets.push('status = ?');
      values.push(updates.status);
      if (updates.status === 'completed') {
        sets.push('completed_at = ?');
        values.push(Date.now()); // Store as milliseconds
      }
    }
    if (updates.name !== undefined) {
      sets.push('name = ?');
      values.push(updates.name);
    }
    if (updates.description !== undefined) {
      sets.push('description = ?');
      values.push(updates.description);
    }
    if (updates.agent !== undefined) {
      sets.push('agent = ?');
      values.push(updates.agent);
    }
    if (updates.priority !== undefined) {
      sets.push('priority = ?');
      values.push(updates.priority);
    }
    if (updates.notes !== undefined) {
      sets.push('notes = ?');
      values.push(updates.notes);
    }
    if (updates.summary !== undefined) {
      sets.push('summary = ?');
      values.push(updates.summary);
    }
    if (updates.dependencies !== undefined) {
      sets.push('dependencies = ?');
      values.push(JSON.stringify(updates.dependencies));
    }
    if (updates.relatedFiles !== undefined || updates.related_files !== undefined) {
      sets.push('related_files = ?');
      values.push(JSON.stringify(updates.relatedFiles || updates.related_files));
    }

    // Always update timestamp and increment version
    sets.push('updated_at = ?');
    values.push(Date.now()); // Store as milliseconds
    sets.push('version = version + 1');

    // Add taskId and version for WHERE clause
    values.push(taskId);
    values.push(expectedVersion);

    // 1. Update SQLite with optimistic locking
    const result = db.prepare(`
      UPDATE workflow_tasks
      SET ${sets.join(', ')}
      WHERE id = ? AND version = ?
    `).run(...values);

    if (result.changes > 0) {
      // 2. Sync to Shrimp (async)
      setImmediate(() => syncToShrimpFile(taskId));

      // 3. WebSocket broadcast
      broadcastUpdate('task_updated', { taskId, updates });

      return { success: true, data: { taskId, updates } };
    }

    // Version conflict - retry with new version
    console.log(`[Sync] Version conflict for task ${taskId}, retrying...`);
    retries--;
    expectedVersion = undefined; // Force re-fetch of version

    // Small delay before retry
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  return { success: false, error: 'Version conflict - too many retries' };
}

// Delete workflow task
export async function deleteWorkflowTask(taskId: string) {
  const result = db.prepare(`
    DELETE FROM workflow_tasks WHERE id = ?
  `).run(taskId);

  if (result.changes > 0) {
    // Sync deletion to Shrimp
    setImmediate(async () => {
      try {
        const fileContent = await readFile(SHRIMP_TASKS_FILE, 'utf-8');
        const shrimpData = JSON.parse(fileContent);
        const tasks = shrimpData.tasks || [];

        // Remove task from array
        const filteredTasks = tasks.filter((t: any) => t.id !== taskId);

        // Write updated file
        await writeFile(
          SHRIMP_TASKS_FILE,
          JSON.stringify({ tasks: filteredTasks }, null, 2),
          'utf-8'
        );
      } catch (error) {
        console.error('[Sync] Failed to delete from Shrimp:', error);
      }
    });

    // WebSocket broadcast
    broadcastUpdate('task_deleted', { taskId });

    return { success: true };
  }

  return { success: false, error: 'Task not found' };
}

// Search tasks with optional KRAG enhancement
export async function searchTasksWithKRAG(query: string) {
  try {
    // Try KRAG on port 8002
    const response = await fetch('http://localhost:8002/api/search-memory-nodes', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        query: `task ${query}`,
        entity: 'Procedure',
        max_nodes: 20
      })
    });

    if (response.ok) {
      const kragData = await response.json();
      // TODO: Merge with SQLite results
      console.log('[KRAG] Enhanced search results:', kragData);
    }
  } catch (error) {
    console.log('[KRAG] Fallback to SQLite-only search');
  }

  // SQLite search
  const searchTerm = `%${query}%`;
  const tasks = db.prepare(`
    SELECT * FROM workflow_tasks
    WHERE name LIKE ? OR description LIKE ? OR notes LIKE ?
    ORDER BY updated_at DESC
    LIMIT 50
  `).all(searchTerm, searchTerm, searchTerm) as any[];

  return tasks.map(task => ({
    ...task,
    dependencies: JSON.parse(task.dependencies || '[]'),
    related_files: JSON.parse(task.related_files || '[]')
  }));
}

