    setImmediate(async () => {
      try {
        const fileContent = await readFile(SHRIMP_TASKS_FILE, 'utf-8');
        const shrimpData = JSON.parse(fileContent);
        const tasks = shrimpData.tasks || [];

        // Remove task from array
        const filteredTasks = tasks.filter((t: any) => t.id !== taskId);

        // Write updated file
        await writeFile(
          SHRIMP_TASKS_FILE,
          JSON.stringify({ tasks: filteredTasks }, null, 2),
          'utf-8'
        );
      } catch (error) {
