  `).all(searchTerm, searchTerm, searchTerm) as any[];

  return tasks.map(task => ({
    ...task,
    dependencies: JSON.parse(task.dependencies || '[]'),
    related_files: JSON.parse(task.related_files || '[]')
  }));
}

