import { Database } from 'bun:sqlite';
import { watch } from 'fs';
import { readFile, writeFile } from 'fs/promises';
import path from 'path';

// Shrimp tasks file location
const SHRIMP_TASKS_FILE = '/Users/sam/ShrimpData/claude-code-hooks-mastery/tasks.json';
const SHRIMP_BACKUP_DIR = '/Users/sam/ShrimpData/claude-code-hooks-mastery/memory';

// WebSocket connections for real-time updates
const wsConnections = new Set<any>();

// Database instance
let db: Database;

// Debounce timer for file watcher
let debounceTimer: NodeJS.Timeout | null = null;
const DEBOUNCE_DELAY = 500; // 500ms debounce

// Track sync status to prevent loops
let isSyncing = false;

export function initWorkflowBridge(database: Database) {
  db = database;

  // Start file watcher
  initShrimpSync();

  // Initial sync on startup
  syncFromShrimpToSQLite().catch(console.error);
}

// Add WebSocket connection
export function addWebSocketConnection(ws: any) {
  wsConnections.add(ws);
  ws.on('close', () => wsConnections.delete(ws));
}

// Broadcast to all connected clients
function broadcastUpdate(event: string, data: any) {
  const message = JSON.stringify({ event, data });
  wsConnections.forEach(ws => {
    if (ws.readyState === 1) { // OPEN
      ws.send(message);
    }
  });
}

// File watcher for automatic synchronization with debounce
function initShrimpSync() {
  // Watch for changes in Shrimp tasks file
  watch(SHRIMP_TASKS_FILE, async (eventType) => {
    if (eventType === 'change' && !isSyncing) {
      // Clear existing timer
      if (debounceTimer) {
        clearTimeout(debounceTimer);
      }

      // Set new debounced sync
      debounceTimer = setTimeout(async () => {
        console.log('[Sync] Detected change in Shrimp tasks.json (debounced)');
        await syncFromShrimpToSQLite();
      }, DEBOUNCE_DELAY);
    }
  });

  console.log('[Sync] File watcher initialized with debounce for:', SHRIMP_TASKS_FILE);
}

// Sync from Shrimp → SQLite (READ)
export async function syncFromShrimpToSQLite() {
  try {
    const fileContent = await readFile(SHRIMP_TASKS_FILE, 'utf-8');
    const shrimpData = JSON.parse(fileContent);
    const tasks = shrimpData.tasks || [];

    console.log(`[Sync] Syncing ${tasks.length} tasks from Shrimp to SQLite`);

    const upsertStmt = db.prepare(`
      INSERT OR REPLACE INTO workflow_tasks (
        id, name, description, status, agent, session_id,
        implementation_guide, verification_criteria, analysis_result,
        notes, summary, dependencies, related_files, priority,
        created_at, updated_at, completed_at, shrimp_sync_version, version
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    const transaction = db.transaction(() => {
      for (const task of tasks) {
        upsertStmt.run(
          task.id,
          task.name,
          task.description || null,
          task.status || 'pending',
          task.agent || 'primary',
          task.session_id || 'default',
          task.implementationGuide || null,
          task.verificationCriteria || null,
          task.analysisResult || null,
          task.notes || null,
          task.summary || null,
          JSON.stringify(task.dependencies || []),
          JSON.stringify(task.relatedFiles || []),
          task.priority || 'medium',
          task.createdAt ? new Date(task.createdAt).getTime() : Date.now(),
          task.updatedAt ? new Date(task.updatedAt).getTime() : Date.now(),
          task.completedAt ? new Date(task.completedAt).getTime() : null,
          Date.now(), // sync version
          1 // version for optimistic locking
        );
      }
    });

    transaction();

    // Broadcast update to WebSocket clients
    broadcastUpdate('tasks_synced', { count: tasks.length, source: 'shrimp' });

    console.log(`[Sync] Successfully synced ${tasks.length} tasks`);
    return tasks;

  } catch (error) {
    console.error('[Sync] Failed to sync from Shrimp:', error);
    return [];
  }
}

// Write-through: SQLite → Shrimp (WRITE)
export async function syncToShrimpFile(taskId?: string) {
  // Set sync flag to prevent loop
  isSyncing = true;

  try {
    // Read current Shrimp state
    let shrimpData = { tasks: [] };
    try {
      const fileContent = await readFile(SHRIMP_TASKS_FILE, 'utf-8');
      shrimpData = JSON.parse(fileContent);
    } catch (error) {
      console.log('[Sync] Creating new Shrimp tasks file');
    }

    let shrimpTasks = shrimpData.tasks || [];

    if (taskId) {
      // Sync single task
      const sqliteTask = db.prepare(`
        SELECT * FROM workflow_tasks WHERE id = ?
      `).get(taskId) as any;

      if (sqliteTask) {
        // Convert SQLite format → Shrimp format
        const shrimpTask = {
          id: sqliteTask.id,
          name: sqliteTask.name,
          description: sqliteTask.description,
          status: sqliteTask.status,
          agent: sqliteTask.agent,
          session_id: sqliteTask.session_id,
          notes: sqliteTask.notes,
          dependencies: JSON.parse(sqliteTask.dependencies || '[]'),
          relatedFiles: JSON.parse(sqliteTask.related_files || '[]'),
          implementationGuide: sqliteTask.implementation_guide,
          verificationCriteria: sqliteTask.verification_criteria,
          analysisResult: sqliteTask.analysis_result,
          summary: sqliteTask.summary,
          priority: sqliteTask.priority,
          createdAt: new Date(sqliteTask.created_at).toISOString(),
          updatedAt: new Date(sqliteTask.updated_at).toISOString(),
          completedAt: sqliteTask.completed_at 
            ? new Date(sqliteTask.completed_at).toISOString()
            : undefined
        };

        // Update or insert in array
        const index = shrimpTasks.findIndex((t: any) => t.id === taskId);
        if (index >= 0) {
          shrimpTasks[index] = shrimpTask;
        } else {
          shrimpTasks.push(shrimpTask);
        }
      }
    } else {
      // Full sync (all tasks)
      const allTasks = db.prepare(`
        SELECT * FROM workflow_tasks ORDER BY created_at DESC
      `).all() as any[];

      // Convert all tasks
      shrimpTasks = allTasks.map(task => ({
        id: task.id,
        name: task.name,
        description: task.description,
        status: task.status,
        agent: task.agent,
        session_id: task.session_id,
        notes: task.notes,
        dependencies: JSON.parse(task.dependencies || '[]'),
        relatedFiles: JSON.parse(task.related_files || '[]'),
        implementationGuide: task.implementation_guide,
        verificationCriteria: task.verification_criteria,
        analysisResult: task.analysis_result,
        summary: task.summary,
        priority: task.priority,
        createdAt: new Date(task.created_at).toISOString(),
        updatedAt: new Date(task.updated_at).toISOString(),
        completedAt: task.completed_at 
          ? new Date(task.completed_at).toISOString()
          : undefined
      }));
    }

    // Write updated file
    await writeFile(
      SHRIMP_TASKS_FILE,
      JSON.stringify({ tasks: shrimpTasks }, null, 2),
      'utf-8'
    );

    console.log(`[Sync] Successfully synced to Shrimp file`);
    return true;

  } catch (error) {
    console.error('[Sync] Failed to sync to Shrimp:', error);
    return false;
  } finally {
    // Reset sync flag after a delay to allow file system to settle
    setTimeout(() => {
      isSyncing = false;
    }, 100);
  }
}

