import { initDatabase, insertEvent, getFilterOptions, getRecentEvents, db } from './db';
import type { HookEvent } from './types';
import { 
  createTheme, 
  updateThemeById, 
  getThemeById, 
  searchThemes, 
  deleteThemeById, 
  exportThemeById, 
  importTheme,
  getThemeStats 
} from './theme';
import { cleanupEventsDB } from './cleanup';
import { 
  initWorkflowBridge, 
  addWebSocketConnection,
  getWorkflowTasks,
  createWorkflowTask,
  updateWorkflowTask,
  deleteWorkflowTask,
  searchTasksWithKRAG
} from './workflow-bridge';

// Initialize database
initDatabase();

// Initialize workflow bridge with database
initWorkflowBridge(db);

// Run cleanup on startup
cleanupEventsDB();

// Schedule cleanup every 6 hours
setInterval(() => {
  console.log('[Server] Running scheduled database cleanup...');
  cleanupEventsDB();
}, 6 * 60 * 60 * 1000);

// Store WebSocket clients
const wsClients = new Set<any>();

// Create Bun server with HTTP and WebSocket support
const server = Bun.serve({
  port: 4000,

  // WebSocket configuration for real-time events
  websocket: {
    open(ws) {
      console.log('WebSocket client connected');
      wsClients.add(ws);
      // Add to workflow bridge for task updates
      addWebSocketConnection(ws);
    },

    message(ws, message) {
      try {
        const data = JSON.parse(message as string);

        // Handle different message types
        if (data.type === 'task_completion_event' && data.data) {
          // Insert event into database - preserve all enhanced data including agent_context
          const event: HookEvent = {
            source_app: data.data.source_app || 'cc-hook-multi-agent-obvs',
            session_id: data.data.session_id || 'unknown',
            hook_event_type: data.data.hook_event_name || 'PostToolUse',
            payload: JSON.stringify(data.data), // This includes agent_context and enhanced_timestamp
            timestamp: data.data.enhanced_timestamp || data.timestamp || Date.now()
          };

          const savedEvent = insertEvent(event);

          // Broadcast to all clients
          const broadcastMessage = JSON.stringify({ 
            type: 'event', 
            data: savedEvent
          });

          wsClients.forEach(client => {
            try {
              client.send(broadcastMessage);
            } catch (err) {
              wsClients.delete(client);
            }
          });
        }
      } catch (error) {
        console.error('WebSocket message error:', error);
      }
    },

    close(ws) {
      console.log('WebSocket client disconnected');
      wsClients.delete(ws);
    }
  },

  async fetch(req: Request) {
    const url = new URL(req.url);

    // Handle CORS
    const headers = {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type',
    };

    // Handle preflight
    if (req.method === 'OPTIONS') {
      return new Response(null, { headers });
    }

    // GET /health - Health check endpoint
    if (url.pathname === '/health' && req.method === 'GET') {
      const healthData = {
        status: 'healthy',
        timestamp: new Date().toISOString(),
        version: '1.0.0',
        services: {
          database: 'ok',
          websocket: 'ok'
        },
        metrics: {
          activeConnections: wsClients.size,
          uptime: process.uptime(),
          memoryUsage: process.memoryUsage()
        }
      };

      return new Response(JSON.stringify(healthData), {
        headers: { ...headers, 'Content-Type': 'application/json' }
      });
    }

    // POST /events - Receive new events (Simplified)
    if (url.pathname === '/events' && req.method === 'POST') {
      try {
        const event: HookEvent = await req.json();

        // Validate required fields
        if (!event.source_app || !event.session_id || !event.hook_event_type || !event.payload) {
          return new Response(JSON.stringify({ error: 'Missing required fields' }), {
            status: 400,
            headers: { ...headers, 'Content-Type': 'application/json' }
          });
        }

        // Insert event into database
        const savedEvent = insertEvent(event);

        // Broadcast to all WebSocket clients (simplified)
        const message = JSON.stringify({ 
          type: 'event', 
          data: savedEvent
        });

        wsClients.forEach(client => {
          try {
            client.send(message);
          } catch (err) {
            // Client disconnected, remove from set
            wsClients.delete(client);
          }
        });

        return new Response(JSON.stringify(savedEvent), {
          headers: { ...headers, 'Content-Type': 'application/json' }
        });
      } catch (error) {
        console.error('Error processing event:', error);
        return new Response(JSON.stringify({ error: 'Invalid request' }), {
          status: 400,
          headers: { ...headers, 'Content-Type': 'application/json' }
        });
      }
    }

    // GET /events/filter-options - Get available filter options
    if (url.pathname === '/events/filter-options' && req.method === 'GET') {
      const options = getFilterOptions();
      return new Response(JSON.stringify(options), {
        headers: { ...headers, 'Content-Type': 'application/json' }
      });
    }

    // GET /events/recent - Get recent events
    if (url.pathname === '/events/recent' && req.method === 'GET') {
      const limit = parseInt(url.searchParams.get('limit') || '100');
      const events = getRecentEvents(limit);
      return new Response(JSON.stringify(events), {
        headers: { ...headers, 'Content-Type': 'application/json' }
      });
    }

    // Workflow Bridge API endpoints

    // GET /api/workflow/tasks - Get workflow tasks for Kanban board
    if (url.pathname === '/api/workflow/tasks' && req.method === 'GET') {
      try {
        const sessionId = url.searchParams.get('sessionId') || undefined;
